def by_art(a): return next((y for y in CAT if y["a"] == a), None)
def buy_with(x):
    """Блок «С этим берут»: что обычно докупают к этому изделию (уголок к панелям, плинтус и карниз к стене и т. п.)."""
    c, a = x["c"], x["a"]
    picks = {"panel": ["A116", "A005", "A172", "A11-80"], "color": ["A116", "A005", "A38"], "plinth": ["A172", "A116", "A35"],
             "led": [], "cornice": ["A005", "A35", "A116"], "mold": ["A005", "A172", "A35/2"], "corner": ["A907", "A005", "A172"]}.get(c, [])
    if c == "plinth" and a in LED_ARTS: picks = ["A503", "A172", "A116"]
    if c == "cornice" and a in LED_ARTS: picks = ["A11-80", "A005", "A116"]
    items = [by_art(p) for p in picks if p != a and by_art(p)]
    if not items: return ""
    why = {"corner": "закрыть торцы панелей на внешнем углу", "plinth": "плинтус в тот же цвет, что и стена", "cornice": "стык стены и потолка",
           "mold": "рамки и панно на соседней стене", "panel": "реечная панель к уголку"}
    return ('<section class="rel with"><div class="wrap"><h2>С этим берут</h2><p class="note">Что обычно докупают вместе с %s (%s): %s.</p><div class="grid">%s</div></div></section>'
            % (esc(a), esc(KIND[c].lower()), "; ".join(sorted({why.get(y["c"], y["c"]) for y in items})), "".join(card(y, ROOT) for y in items)))

