def category_page(code, sl, menu, h1, intro, ctitle, cdesc):
    items = cat_items(code)
    url = "%s/catalog/%s/" % (BASE, sl)
    crumb_items = [("Главная", ROOT), (menu, "")]
    first_ph = next((photo(x["a"]) for x in items if photo(x["a"])), "")
    og_img = BASE + "/" + first_ph if first_ph else BASE + "/og.jpg"
    faq = FAQ.get(code, [])
    faq_html = ('<section class="faq"><h2>Вопросы и ответы</h2>%s</section>' % "".join(
        '<details><summary>%s</summary><p>%s</p></details>' % (esc(q), esc(a_)) for q, a_ in faq)) if faq else ""
    ld = ('<script type="application/ld+json">%s</script>' % json.dumps({"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [
        {"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a_}} for q, a_ in faq]}, ensure_ascii=False)) if faq else ""
    ld += '<script type="application/ld+json">%s</script>' % json.dumps({
        "@context": "https://schema.org", "@type": "CollectionPage", "name": h1, "url": url, "description": intro,
        "mainEntity": {"@type": "ItemList", "numberOfItems": len(items), "itemListElement": [
            {"@type": "ListItem", "position": i + 1, "url": "%s/p/%s/" % (BASE, slug(x["a"])), "name": x["n"]} for i, x in enumerate(items)]}}, ensure_ascii=False)
    H2 = '<h2 style="font-size:18px;margin:22px 0 10px" id="%s">%s</h2>'
    if code == "color":
        groups = []
        for s in ("2", "3", "5"):
            g = [x for x in items if series(x) == s]
            if g: groups.append(H2 % ("s" + s, "Серия %s — %s, %d шт в коробке" % (s, WOOD_NAMES[s], g[0]["b"])) + '<div class="grid">%s</div>' % "".join(card(x, ROOT) for x in g))
        grid = "".join(groups)
    elif code == "plinth":
        hs = sorted({x["w"] for x in items})
        nav = '<nav class="heights" aria-label="Плинтус по высоте"><span class="note">Высота плинтуса:</span> %s</nav>' % " ".join('<a href="#h%d">%d мм</a>' % (h, h) for h in hs)
        groups = []
        for h in hs:
            g = [x for x in items if x["w"] == h]
            led = [x for x in g if x["a"] in LED_ARTS]
            groups.append(H2 % ("h%d" % h, "Плинтус напольный %d мм — %d %s%s" % (h, len(g), "модель" if len(g) == 1 else ("модели" if len(g) < 5 else "моделей"), ", в том числе с подсветкой" if led else "")) + '<div class="grid">%s</div>' % "".join(card(x, ROOT) for x in g))
        grid = nav + "".join(groups)
    elif code == "wall":
        white = [x for x in items if x["c"] == "panel"]; dec = [x for x in items if x["c"] == "color"]
        grid = (H2 % ("white", "Белые реечные панели под покраску — %d профилей, цена от %s ₽/м²" % (len(white), fmt(min(m2(x) for x in white if m2(x))))) + '<div class="grid">%s</div>' % "".join(card(x, ROOT) for x in white) +
                H2 % ("decor", "Панели под дерево и под бетон с готовым декором — %d, цена от %s ₽/м²" % (len(dec), fmt(min(m2(x) for x in dec if m2(x))))) + '<div class="grid">%s</div>' % "".join(card(x, ROOT) for x in dec) +
                wall_hub_blocks())
    else:
        grid = '<div class="grid">%s</div>' % "".join(card(x, ROOT) for x in items)
    t, desc = ctitle, cdesc
    body = (header(ROOT) + '<main><div class="wrap">' + crumbs(crumb_items) +
            '<div class="head" style="margin-top:6px"><div><h1 style="font-size:clamp(24px,4.2vw,38px)">%s</h1><p class="catintro">%s</p></div></div>' % (esc(h1), esc(intro)) +
            sections_nav(code, ROOT) + grid +
            '<p class="note" style="margin-top:18px">Цены предварительные, за штуку, без НДС. Нажмите на товар — там фото, 3D, профиль, размеры, цена и заявка.</p>' + faq_html + '</div>' +
            lead_form(None) + "</main>" + footer(ROOT) +
            '<script>window.P=%s</script><script src="%sassets/p.js?v=%s"></script></body></html>' % (json.dumps({"root": ROOT, "list": True, "shop": {"telegram": SHOP["telegram"], "max": SHOP.get("max", "")}}, ensure_ascii=False), ROOT, VER))
    return head(t, desc, url, og_img, ld, ROOT) + body

def wall_hub_blocks():
    """Хаб «Стеновые панели»: материал, где применять, расчёт, доставка — факты без лишних слов."""
    return ('<div class="hub">'
            '<section><h2>Из чего сделаны панели</h2><p>Полистирол высокой плотности — его называют дюрополимером. Это плотный литой полимер с твёрдой гладкой поверхностью: панель не ломается при монтаже, '
            'держит бытовые удары, не впитывает воду и не разбухает, моется влажной тряпкой. Белые панели поставляются с грунтом под покраску и красятся любой краской для стен; '
            'панели под дерево и под бетон идут с готовым декором на чёрной основе. Все панели длиной 3 м, толщина 10–12 мм, режутся ножовкой с мелким зубом или лобзиком.</p></section>'
            '<section><h2>Где ставят стеновые панели</h2><ul>'
            '<li><b>ТВ-зона и стена за диваном</b> — объёмный рельеф, кабель ТВ прячется в молдинге с кабель-каналом A35/2.</li>'
            '<li><b>Спальня</b> — изголовье кровати во всю стену, панели под дерево или окрашенные в цвет стен.</li>'
            '<li><b>Прихожая и коридор</b> — твёрдая поверхность не боится сумок, колёс и обуви; низ закрывают плинтусом в тот же цвет.</li>'
            '<li><b>Кухня</b> — обеденная зона и стена у стола; вплотную к плите не ставят.</li>'
            '<li><b>Санузел</b> — материал влагостойкий: подходит для ванной с вытяжкой вне зоны прямого попадания воды (не в душевой).</li></ul></section>'
            '<section><h2>Как рассчитать и сколько стоит</h2><p>Ширина стены ÷ ширина панели = число панелей в ряд, плюс 10 %% на подрезку. Цена за м² — от %s ₽ у белых панелей и от %s ₽ у панелей с декором. '
            'На странице каждой панели есть <b>«3D · моя стена»</b>: введите ширину и высоту, окна и двери — стена построится в 3D и тут же посчитаются штуки, коробки и сумма. '
            'Расчёт стены целиком — с плинтусом, потолочным плинтусом и уголками — на <a href="%s#calc">главной странице</a>.</p></section>'
            '<section><h2>Доставка и самовывоз</h2><p>Самовывоз со склада в Санкт-Петербурге — бесплатно. Доставка по Петербургу 1–2 дня, по Ленобласти 1–3 дня после оплаты, по тарифу перевозчика; '
            'в другие города — транспортной компанией. Панели 3 м едут в машине с кузовом от 3 м. Продаём поштучно и коробками; цены без НДС, компаниям и ИП — по счёту с закрывающими документами.</p></section>'
            '</div>') % (fmt(min(m2(x) for x in CAT if x["c"] == "panel" and m2(x))), fmt(min(m2(x) for x in CAT if x["c"] == "color" and m2(x))), ROOT)

