from articles import ARTICLES, SVG   # noqa: E402

def art_url(a): return "%s/stati/%s/" % (BASE, a["slug"])
def fill_article(body):
    """{p:A907} → ссылка на товар, {c:plintusy} → раздел, {img:A907|подпись} → фото, {svg:corner} → схема."""
    def prod(m):
        x = by_art(m.group(1)); return '<a href="%sp/%s/">%s</a>' % (ROOT, slug(x["a"]), esc(x["a"])) if x else esc(m.group(1))
    def catl(m):
        c = next((c for c in CATS if c[1] == m.group(1)), None); return '<a href="%scatalog/%s/">%s</a>' % (ROOT, c[1], esc(c[2].lower() if c[0] != "wall" else c[2])) if c else m.group(1)
    def img(m):
        a, cap = m.group(1), m.group(2); ph = photo(a)
        return ('<figure><a href="%sp/%s/"><img src="%s%s" alt="%s" loading="lazy" width="790" height="449"></a><figcaption>%s</figcaption></figure>' % (ROOT, slug(a), ROOT, ph, esc(cap), esc(cap))) if ph else ""
    body = re.sub(r"\{p:([^}]+)\}", prod, body)
    body = re.sub(r"\{c:([^}]+)\}", catl, body)
    body = re.sub(r"\{img:([^|}]+)\|([^}]+)\}", img, body)
    body = re.sub(r"\{svg:([^}]+)\}", lambda m: SVG.get(m.group(1), ""), body)
    return body

def article_page(a, others):
    url = art_url(a); first_img = re.search(r"\{img:([^|}]+)", a["body"]); ph = photo(first_img.group(1)) if first_img else ""
    og_img = (BASE + "/" + ph) if ph else BASE + "/og.jpg"
    crumb_items = [("Главная", ROOT), ("Статьи", ROOT + "stati/"), (a["title"], "")]
    ld = {"@context": "https://schema.org", "@type": "Article", "headline": a["title"], "description": a["description"], "datePublished": a["date"], "dateModified": a["date"],
          "mainEntityOfPage": url, "inLanguage": "ru", "author": {"@type": "Organization", "name": "Наш декор", "url": BASE + "/"},
          "publisher": {"@type": "Organization", "name": "Наш декор", "url": BASE + "/", "logo": {"@type": "ImageObject", "url": BASE + "/apple-touch-icon.png"}}}
    if ph: ld["image"] = [og_img]
    extra = '<script type="application/ld+json">%s</script><script type="application/ld+json">%s</script>' % (
        json.dumps(ld, ensure_ascii=False), json.dumps(crumbs_ld(crumb_items, lambda h: BASE + "/" + h.replace(ROOT, "", 1) if h != ROOT else BASE + "/"), ensure_ascii=False))
    more = "".join('<li><a href="%sstati/%s/">%s</a></li>' % (ROOT, o["slug"], esc(o["title"])) for o in others if o["slug"] != a["slug"])
    body = (header(ROOT) + '<main><div class="wrap">' + crumbs(crumb_items) +
            '<article class="article"><h1>%s</h1><p class="lead">%s</p><p class="meta">Наш декор · %s</p>%s'
            '<p class="shipline">Отправляем в Москву и любой регион транспортной компанией — <a href="%sdostavka/">как считается доставка</a>. Самовывоз в Санкт-Петербурге бесплатно.</p>'
            '<aside class="more-art"><h2>Ещё по теме</h2><ul>%s</ul></aside></article></div>' % (esc(a["h1"]), esc(a["lead"]), fmt_date(a["date"]), fill_article(a["body"]), ROOT, more) +
            lead_form(None) + "</main>" + footer(ROOT) +
            '<script>window.P=%s</script><script src="%sassets/p.js?v=%s"></script></body></html>' % (json.dumps({"root": ROOT, "list": True, "shop": {"telegram": SHOP["telegram"], "max": SHOP.get("max", "")}}, ensure_ascii=False), ROOT, VER))
    return head(a["title"] + " | Наш декор", a["description"], url, og_img, extra, ROOT) + body

def fmt_date(s):
    y, m, d = s.split("-"); return "%d %s %s" % (int(d), ["января", "февраля", "марта", "апреля", "мая", "июня", "июля", "августа", "сентября", "октября", "ноября", "декабря"][int(m) - 1], y)

def articles_index():
    url = BASE + "/stati/"; root = "../"
    crumb_items = [("Главная", root), ("Статьи", "")]
    items = "".join('<li><a href="%s%s/"><b>%s</b><span>%s</span></a></li>' % (root + "stati/", a["slug"], esc(a["title"]), esc(a["description"])) for a in ARTICLES)
    ld = '<script type="application/ld+json">%s</script>' % json.dumps({"@context": "https://schema.org", "@type": "CollectionPage", "name": "Статьи о плинтусах, молдингах и стеновых панелях", "url": url,
          "mainEntity": {"@type": "ItemList", "itemListElement": [{"@type": "ListItem", "position": i + 1, "url": art_url(a), "name": a["title"]} for i, a in enumerate(ARTICLES)]}}, ensure_ascii=False)
    body = (header(root) + '<main><div class="wrap">' + crumbs(crumb_items) +
            '<div class="head" style="margin-top:6px"><div><h1 style="font-size:clamp(24px,4.2vw,38px)">Статьи: как выбрать, смонтировать и покрасить</h1>'
            '<p class="catintro">Короткие практические разборы про плинтусы, молдинги, потолочные плинтусы и стеновые панели из полистирола высокой плотности: как резать углы, чем клеить, как считать и красить.</p></div></div>'
            '<ul class="artlist">%s</ul></div>' % items + lead_form(None) + "</main>" + footer(root) +
            '<script>window.P=%s</script><script src="%sassets/p.js?v=%s"></script></body></html>' % (json.dumps({"root": root, "list": True, "shop": {"telegram": SHOP["telegram"], "max": SHOP.get("max", "")}}, ensure_ascii=False), root, VER))
    return head("Статьи о плинтусах, молдингах и стеновых панелях — как выбрать и смонтировать | Наш декор",
                "Практические статьи: как отрезать угол потолочного плинтуса, чем клеить плинтус из дюрополимера, монтаж стеновых панелей, покраска, что такое дюрополимер, молдинги и рейки в интерьере.", url, BASE + "/og.jpg", ld, root) + body

# ---------- доставка в Москву и по России ----------
def delivery_page():
    root = "../"; url = BASE + "/dostavka/"
    crumb_items = [("Главная", root), ("Доставка в Москву и по России", "")]
    faq = [
        ("Сколько идёт груз до Москвы?", "Из Санкт-Петербурга до терминала транспортной компании в Москве — обычно 2–3 дня после сдачи груза, доставка до двери добавляет день. Точный срок по вашему адресу показывает калькулятор перевозчика — пришлём его вместе со счётом."),
        ("Сколько стоит доставка?", "Считается по тарифу транспортной компании от веса и объёма груза и расстояния. Мы считаем её заранее по калькулятору перевозчика и пишем в счёт отдельной строкой — или оформляем отправку с оплатой доставки получателем при получении, если вам так удобнее."),
        ("Есть ли наценка за панели 3 м?", "У ПЭК — нашего основного перевозчика — наценка за длину начинается с 5 м, поэтому панели 3 м и плинтусы 2 м едут по обычному тарифу. У других компаний доплата за длинномер бывает — поэтому по умолчанию отправляем ПЭК."),
        ("Можно ли получить до двери?", "Да: до терминала в вашем городе — дешевле, до двери — по тарифу перевозчика за адресную доставку. Панели 3 м при доставке до двери требуют машины с кузовом от 3 м; это учитывает сам перевозчик."),
        ("Как упакован груз?", "Панели — в заводских коробках по 10–12 шт (коробка около 3000×185×125 мм), плинтусы и молдинги — в коробках по 2 м. Для межгорода советуем дополнительную жёсткую упаковку перевозчика (обрешётка или паллетный борт) — она оплачивается по тарифу перевозчика и защищает углы коробок."),
        ("Что делать при получении?", "Осмотрите упаковку при приёмке и пересчитайте места по накладной. Если коробка повреждена — вскройте при сотруднике перевозчика и составьте акт: по акту перевозчик возмещает ущерб, а мы заменим повреждённые изделия."),
    ]
    ld = '<script type="application/ld+json">%s</script>' % json.dumps({"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [
        {"@type": "Question", "name": q, "acceptedAnswer": {"@type": "Answer", "text": a_}} for q, a_ in faq]}, ensure_ascii=False)
    ld += '<script type="application/ld+json">%s</script>' % json.dumps(crumbs_ld(crumb_items, lambda h: BASE + "/" if h == root else url), ensure_ascii=False)
    faq_html = '<section class="faq"><h2>Вопросы и ответы</h2>%s</section>' % "".join('<details><summary>%s</summary><p>%s</p></details>' % (esc(q), esc(a_)) for q, a_ in faq)
    body = (header(root) + '<main><div class="wrap">' + crumbs(crumb_items) +
            '<article class="article"><h1>Доставка в Москву и по России</h1>'
            '<p class="lead">Отправляем стеновые панели, плинтусы, молдинги и уголки в Москву и любой регион транспортной компанией со склада в Санкт-Петербурге. Самовывоз в СПб — бесплатно.</p>'
            '<h2>Как это устроено</h2><ol>'
            '<li>Вы оставляете заказ на сайте или присылаете список артикулов — мы подтверждаем наличие и считаем доставку по калькулятору перевозчика до вашего города: до терминала или до двери.</li>'
            '<li>Присылаем счёт или ссылку на оплату. Для отправки в другой город заказ оплачивается полностью до отгрузки: картой или СБП по ссылке, компаниям и ИП — по счёту с закрывающими документами.</li>'
            '<li>Сдаём груз перевозчику в течение 1–2 рабочих дней после оплаты (товар под заказ — после прихода на склад, срок называем заранее) и присылаем номер накладной для отслеживания.</li>'
            '<li>Вы получаете груз на терминале в своём городе или по адресу — по выбору при заказе.</li></ol>'
            '<h2>Перевозчики и сроки</h2>'
            '<p>Основной перевозчик — <b>ПЭК</b>: у него нет наценки за длину до 5 м, поэтому панели 3 м едут по обычному тарифу сборного груза, а терминалы есть почти во всех городах. По согласованию отправляем и другими компаниями — Деловые Линии, КИТ; небольшие посылки (молдинги, уголки, клей) — СДЭК.</p>'
            '<p>Ориентир по срокам из Санкт-Петербурга: Москва и Московская область — 2–3 дня до терминала; Центральная Россия и Поволжье — 3–5 дней; Урал и Сибирь — 5–10 дней. Точный срок и стоимость до вашего адреса считает калькулятор перевозчика — пришлём расчёт вместе со счётом.</p>'
            '<h2>Стоимость</h2>'
            '<p>Доставка считается по тарифу перевозчика от веса, объёма и расстояния и указывается в счёте отдельной строкой — вы видите её до оплаты. Если удобнее, оформим отправку с оплатой доставки получателем при получении. Адресная доставка до двери дороже доставки до терминала; панели 3 м до двери везёт машина с кузовом от 3 м — это учитывает перевозчик.</p>'
            '<h2>Упаковка</h2>'
            '<p>Панели упакованы в заводские коробки по 10–12 шт (коробка около 3000×185×125 мм), плинтусы, молдинги и уголки — в коробки по 2 м. На межгород советуем заказать у перевозчика дополнительную жёсткую упаковку — обрешётку или паллетный борт: она оплачивается по тарифу перевозчика и защищает углы коробок при перегрузках.</p>'
            '<h2>Получение</h2>'
            '<p>При приёмке пересчитайте места по накладной и осмотрите упаковку. Повреждённую коробку вскройте при сотруднике перевозчика и составьте акт — по нему перевозчик возмещает ущерб, а мы заменяем изделия. Неподошедший товар можно вернуть в течение 7 дней после получения, если он не распилен, не окрашен и не монтировался (подробнее — в <a href="%soferta.html">оферте</a>).</p>'
            '<h2>По Санкт-Петербургу и Ленобласти</h2>'
            '<p>Самовывоз со склада — бесплатно. Доставка по Петербургу 1–2 дня, по Ленобласти 1–3 дня после оплаты, по тарифу перевозчика; стоимость называем до оплаты.</p>'
            '%s<p class="shipline">Вопрос по доставке в ваш город — напишите в форме ниже или в мессенджер, посчитаем за один рабочий день.</p></article></div>' % (root, faq_html) +
            lead_form(None) + "</main>" + footer(root) +
            '<script>window.P=%s</script><script src="%sassets/p.js?v=%s"></script></body></html>' % (json.dumps({"root": root, "list": True, "shop": {"telegram": SHOP["telegram"], "max": SHOP.get("max", "")}}, ensure_ascii=False), root, VER))
    return head("Доставка стеновых панелей и плинтусов в Москву и по России — транспортной компанией | Наш декор",
                "Отправляем стеновые панели 3 м, плинтусы и молдинги в Москву и любой регион транспортной компанией (ПЭК и другие): сроки, как считается стоимость, упаковка, оплата, получение. Самовывоз в СПб бесплатно.",
                url, BASE + "/og.jpg", ld, root) + body

# ---------- сборка ----------
ROOT = "../../"
VER = datetime.datetime.now().strftime("%Y%m%d%H%M")
os.makedirs(os.path.join(SITE, "assets"), exist_ok=True)
open(os.path.join(SITE, "assets", "p.css"), "w", encoding="utf-8").write(BASE_CSS + "\n" + open(os.path.join(HERE, "p.css"), encoding="utf-8").read())
shutil.copy(os.path.join(HERE, "p.js"), os.path.join(SITE, "assets", "p.js"))

pdir = os.path.join(SITE, "p"); cdir = os.path.join(SITE, "catalog"); adir = os.path.join(SITE, "stati"); ddir = os.path.join(SITE, "dostavka")
for d in (pdir, cdir, adir, ddir):
    if os.path.isdir(d): shutil.rmtree(d)
urls = []
for x in CAT:
    d = os.path.join(pdir, slug(x["a"])); os.makedirs(d)
    open(os.path.join(d, "index.html"), "w", encoding="utf-8").write(product_page(x))
    urls.append(("%s/p/%s/" % (BASE, slug(x["a"])), "monthly", "0.7"))
for code, sl, menu, h1, intro, ctitle, cdesc in CATS:
    d = os.path.join(cdir, sl); os.makedirs(d)
    open(os.path.join(d, "index.html"), "w", encoding="utf-8").write(category_page(code, sl, menu, h1, intro, ctitle, cdesc))
    urls.insert(0, ("%s/catalog/%s/" % (BASE, sl), "weekly", "0.8"))
os.makedirs(ddir, exist_ok=True)
open(os.path.join(ddir, "index.html"), "w", encoding="utf-8").write(delivery_page())
urls.append(("%s/dostavka/" % BASE, "monthly", "0.6"))
os.makedirs(adir, exist_ok=True)
open(os.path.join(adir, "index.html"), "w", encoding="utf-8").write(articles_index())
urls.append(("%s/stati/" % BASE, "weekly", "0.6"))
for a in ARTICLES:
    d = os.path.join(adir, a["slug"]); os.makedirs(d)
    open(os.path.join(d, "index.html"), "w", encoding="utf-8").write(article_page(a, ARTICLES))
    urls.append((art_url(a), "monthly", "0.6"))
sm = ['<?xml version="1.0" encoding="UTF-8"?>', '<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">',
      '  <url><loc>%s/</loc><lastmod>%s</lastmod><changefreq>weekly</changefreq><priority>1.0</priority></url>' % (BASE, TODAY)]
sm += ['  <url><loc>%s</loc><lastmod>%s</lastmod><changefreq>%s</changefreq><priority>%s</priority></url>' % (u, TODAY, f, p) for u, f, p in urls]
sm += ['  <url><loc>%s/%s</loc><lastmod>2026-11-09</lastmod><changefreq>yearly</changefreq><priority>%s</priority></url>' % (BASE, f, p) for f, p in (("oferta.html", "0.3"), ("privacy.html", "0.2"), ("consent.html", "0.2"))]
sm.append("</urlset>")
open(os.path.join(SITE, "sitemap.xml"), "w", encoding="utf-8").write("\n".join(sm) + "\n")
print("товаров: %d, разделов: %d, статей: %d, в sitemap: %d адресов, версия ассетов %s" % (len(CAT), len(CATS), len(ARTICLES), len(urls) + 4, VER))
